const items = $input.all();
const leadsRaw = items[0]?.json?.leads || items[0]?.json || [];
const leads = Array.isArray(leadsRaw) ? leadsRaw : [];

const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const weeklyLeads = leads.filter(lead => {
  if (!lead.created_at && !lead.timestamp) return true;
  const d = new Date(lead.created_at || lead.timestamp);
  return d >= sevenDaysAgo;
});

const totalLeads = weeklyLeads.length;

let totalOmzet = 0;
weeklyLeads.forEach(lead => {
  const priceStr = (lead.estimated_price || lead.price || '0').toString();
  const angka = parseInt(priceStr.replace(/[^0-9]/g, ''), 10) || 0;
  totalOmzet += angka;
});

const formatRp = (num) => 'Rp ' + num.toLocaleString('id-ID');

const sumberCount = {};
weeklyLeads.forEach(lead => {
  const src = lead.utm_source || lead.source || 'Lainnya';
  sumberCount[src] = (sumberCount[src] || 0) + 1;
});

const sumberRowsHtml = Object.entries(sumberCount)
  .map(([k, v]) => `<tr><td style="padding:10px 14px;border-bottom:1px solid #334155;">${k}</td><td style="padding:10px 14px;border-bottom:1px solid #334155;font-weight:bold;color:#6366f1;text-align:right;">${v} leads</td></tr>`)
  .join('') || '<tr><td colspan="2" style="padding:10px 14px;color:#94a3b8;">Belum ada leads minggu ini</td></tr>';

const sumberText = Object.entries(sumberCount)
  .map(([k, v]) => '  - ' + k + ': ' + v + ' leads')
  .join('\n') || '  - (Belum ada data minggu ini)';

const tanggal = now.toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const pesan = [
  '*LAPORAN REKAP MINGGUAN — NEXA.3D STUDIO*',
  'Periode: Minggu ini (s/d ' + tanggal + ')',
  '',
  'Total Request Brief: ' + totalLeads + ' leads',
  'Estimasi Total Omzet: ' + formatRp(totalOmzet),
  '',
  'Sumber Lead:',
  sumberText,
  '',
  'Laporan otomatis dari Dashboard WebFunneling & Supabase'
].join('\n');

const pesanHtml = `
<div style="font-family:'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:600px;margin:0 auto;background:#0f172a;color:#f8fafc;border-radius:12px;overflow:hidden;border:1px solid #1e293b;">
  <div style="background:linear-gradient(135deg,#4f46e5,#7c3aed);padding:24px;text-align:center;">
    <h1 style="margin:0;font-size:22px;color:#ffffff;letter-spacing:0.5px;">📊 LAPORAN REKAP MINGGUAN</h1>
    <p style="margin:6px 0 0;font-size:14px;color:#e0e7ff;">Nexa.3D Studio — Executive Performance Summary</p>
  </div>
  <div style="padding:24px;">
    <p style="color:#94a3b8;font-size:13px;margin:0 0 18px;">📅 <strong>Periode:</strong> s/d ${tanggal}</p>

    <div style="margin-bottom:20px;">
      <table style="width:100%;border-collapse:separate;border-spacing:8px 0;">
        <tr>
          <td style="background:#1e293b;padding:16px;border-radius:8px;border-left:4px solid #6366f1;width:50%;">
            <div style="font-size:11px;color:#94a3b8;text-transform:uppercase;letter-spacing:0.5px;">Total Request Brief</div>
            <div style="font-size:24px;font-weight:bold;color:#f8fafc;margin-top:4px;">${totalLeads} <span style="font-size:13px;font-weight:normal;color:#94a3b8;">leads</span></div>
          </td>
          <td style="background:#1e293b;padding:16px;border-radius:8px;border-left:4px solid #10b981;width:50%;">
            <div style="font-size:11px;color:#94a3b8;text-transform:uppercase;letter-spacing:0.5px;">Estimasi Omzet</div>
            <div style="font-size:19px;font-weight:bold;color:#10b981;margin-top:4px;">${formatRp(totalOmzet)}</div>
          </td>
        </tr>
      </table>
    </div>

    <h3 style="font-size:15px;color:#f1f5f9;margin:22px 0 10px;border-bottom:1px solid #334155;padding-bottom:6px;">📡 Rincian Saluran Lead (Acquisition Source)</h3>
    <table style="width:100%;border-collapse:collapse;font-size:14px;color:#cbd5e1;background:#1e293b;border-radius:8px;overflow:hidden;">
      <thead>
        <tr style="background:#334155;text-align:left;color:#94a3b8;font-size:12px;text-transform:uppercase;">
          <th style="padding:10px 14px;">Saluran</th>
          <th style="padding:10px 14px;text-align:right;">Jumlah Lead</th>
        </tr>
      </thead>
      <tbody>
        ${sumberRowsHtml}
      </tbody>
    </table>

    <div style="margin-top:28px;text-align:center;">
      <a href="http://localhost:3001" style="background:#6366f1;color:#ffffff;text-decoration:none;padding:12px 24px;border-radius:6px;font-size:14px;font-weight:600;display:inline-block;">Buka Dashboard WebFunneling →</a>
    </div>
  </div>
  <div style="background:#090d16;padding:14px 24px;text-align:center;font-size:12px;color:#64748b;border-top:1px solid #1e293b;">
    Laporan otomatis ini dikirim ke muhammad.fatih.musyaffa@gmail.com oleh Nexa.3D Studio via n8n & Supabase.
  </div>
</div>
`;

return [{ json: { pesan, pesanHtml, totalLeads, totalOmzet, sumberCount, tanggal } }];

const items = $input.all();
const leadsRaw = items[0]?.json?.leads || items[0]?.json || [];
const leads = Array.isArray(leadsRaw) ? leadsRaw : [];

const totalLeads = leads.length;

const stage1 = Math.max(totalLeads * 15, 100);
const stage2 = Math.max(totalLeads * 5, 20);
const stage3 = Math.max(totalLeads * 2, 10);
const stage4 = totalLeads;

const attrition_1_2 = stage1 > 0 ? Math.round((1 - stage2 / stage1) * 100) : 0;
const attrition_2_3 = stage2 > 0 ? Math.round((1 - stage3 / stage2) * 100) : 0;
const attrition_3_4 = stage3 > 0 ? Math.round((1 - stage4 / stage3) * 100) : 0;

const stages = [
  { label: 'Tahap 1-2 (Iklan ke Website)', rate: attrition_1_2 },
  { label: 'Tahap 2-3 (Website ke Kalkulator)', rate: attrition_2_3 },
  { label: 'Tahap 3-4 (Kalkulator ke Brief)', rate: attrition_3_4 }
];

const worst = stages.reduce((a, b) => a.rate > b.rate ? a : b);

const now = new Date();
const waktu = now.toLocaleString('id-ID', { dateStyle: 'medium', timeStyle: 'short' });

const alertHtml = `
<div style="font-family:'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:600px;margin:0 auto;background:#0f172a;color:#f8fafc;border-radius:12px;overflow:hidden;border:1px solid #ef4444;">
  <div style="background:linear-gradient(135deg,#dc2626,#991b1b);padding:24px;text-align:center;">
    <h1 style="margin:0;font-size:22px;color:#ffffff;letter-spacing:0.5px;">🚨 CRITICAL LEAK ALERT</h1>
    <p style="margin:6px 0 0;font-size:14px;color:#fee2e2;">Deteksi Kebocoran Corong Iklan & Funneling Studio</p>
  </div>
  <div style="padding:24px;">
    <div style="background:#450a0a;border:1px solid #ef4444;border-radius:8px;padding:16px;margin-bottom:20px;">
      <div style="font-size:11px;color:#fca5a5;text-transform:uppercase;font-weight:bold;letter-spacing:0.5px;">Titik Kebocoran Tertinggi:</div>
      <div style="font-size:18px;font-weight:bold;color:#ffffff;margin-top:4px;">${worst.label}</div>
      <div style="font-size:28px;font-weight:bold;color:#f87171;margin-top:6px;">${worst.rate}% <span style="font-size:14px;font-weight:normal;color:#fca5a5;">Drop-off / Attrition</span></div>
    </div>

    <h3 style="font-size:15px;color:#f1f5f9;margin:20px 0 10px;border-bottom:1px solid #334155;padding-bottom:6px;">📊 Rincian Rasio Penurunan per Tahap</h3>
    <table style="width:100%;border-collapse:collapse;font-size:14px;color:#cbd5e1;background:#1e293b;border-radius:8px;overflow:hidden;">
      <thead>
        <tr style="background:#334155;text-align:left;color:#94a3b8;font-size:12px;text-transform:uppercase;">
          <th style="padding:10px 14px;">Tahap Funnel</th>
          <th style="padding:10px 14px;text-align:right;">Tingkat Kebocoran</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td style="padding:10px 14px;border-bottom:1px solid #334155;">Tahap 1-2 (Iklan ke Website)</td>
          <td style="padding:10px 14px;border-bottom:1px solid #334155;text-align:right;font-weight:bold;color:${attrition_1_2 > 60 ? '#f87171' : '#34d399'}">${attrition_1_2}%</td>
        </tr>
        <tr>
          <td style="padding:10px 14px;border-bottom:1px solid #334155;">Tahap 2-3 (Website ke Kalkulator)</td>
          <td style="padding:10px 14px;border-bottom:1px solid #334155;text-align:right;font-weight:bold;color:${attrition_2_3 > 60 ? '#f87171' : '#34d399'}">${attrition_2_3}%</td>
        </tr>
        <tr>
          <td style="padding:10px 14px;">Tahap 3-4 (Kalkulator ke Brief)</td>
          <td style="padding:10px 14px;text-align:right;font-weight:bold;color:${attrition_3_4 > 60 ? '#f87171' : '#34d399'}">${attrition_3_4}%</td>
        </tr>
      </tbody>
    </table>

    <div style="margin-top:24px;text-align:center;">
      <a href="http://localhost:3001" style="background:#ef4444;color:#ffffff;text-decoration:none;padding:12px 24px;border-radius:6px;font-size:14px;font-weight:600;display:inline-block;">Buka Dashboard Evaluasi Funneling →</a>
    </div>
  </div>
  <div style="background:#090d16;padding:14px 24px;text-align:center;font-size:12px;color:#64748b;border-top:1px solid #1e293b;">
    Waktu deteksi: ${waktu} WIB • Dikirim otomatis ke muhammad.fatih.musyaffa@gmail.com via Nexa.3D Studio Anti-Leak
  </div>
</div>
`;

return [{
  json: {
    attrition_rate: worst.rate,
    worst_stage: worst.label,
    worst_rate: worst.rate,
    all_stages: stages,
    attrition_1_2,
    attrition_2_3,
    attrition_3_4,
    total_leads: totalLeads,
    alertHtml
  }
}];
